from pwn import remote
import string

# Constants
HOST = "crypto.chal.csaw.io"
PORT = 8040
PREFIX = "lk"
SUFFIX = "A" * 19
CHAR_SET = string.ascii_lowercase + "_"

# Function to test a single input against the server
def test_input(conn, test_str):
    conn.sendlineafter(b"> ", test_str.encode())
    response = conn.recvline(timeout=5)  # Read response from the server with a timeout
    if response:
        return len(response)
    else:
        print(f"No response received for input: {test_str}")
        return None

# Main function to determine optimal character
def main():
    results = {}
    for char in CHAR_SET:
        test_str = PREFIX + char + SUFFIX
        print(f"Testing input: {test_str}")  # Debug log
        with remote(HOST, PORT) as conn:
            length = test_input(conn, test_str)
        if length is not None:
            results[char] = length
            print(f"Character: {char}, Ciphertext Length: {length}")
        else:
            print(f"Failed to get a valid response for {test_str}")

    if results:
        # Find the character that minimizes the ciphertext length
        min_char = min(results, key=results.get)
        print("Character minimizing length:", min_char)

        # Log results
        with open("length_analysis_debug.txt", "w") as f:
            for char, length in results.items():
                f.write(f"{char}: {length}\n")

if __name__ == "__main__":
    main()
